<?php
require_once __DIR__ . '/../config/bootstrap.php';
require_once __DIR__ . '/../config/auth.php';
require_staff();
if(!isset($_SESSION['user_id'])&&!isset($_SESSION['usuario_id'])){header('Location:../login.php');exit;}require_once '../config/database.php';$db=getDBConnection();$id=filter_input(INPUT_GET,'fumigacion_id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'fumigacion_id',FILTER_VALIDATE_INT);if(!$id){header('Location:fumigaciones_activas.php');exit;}
$q=$db->prepare('SELECT fr.*,c.nombre cliente FROM fumigaciones_realizadas fr LEFT JOIN clientes c ON c.id=fr.cliente_id WHERE fr.id=?');$q->execute([$id]);$f=$q->fetch(PDO::FETCH_ASSOC);if(!$f){http_response_code(404);exit('Fumigación no encontrada');}$q=$db->prepare('SELECT COALESCE(SUM(monto),0) FROM pagos_fumigacion WHERE fumigacion_id=?');$q->execute([$id]);$pagado=(float)$q->fetchColumn();$total=(float)($f['costo_total']??0);$saldo=max(0,$total-$pagado);$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{
 require_once __DIR__.'/../config/ventas.php';$m=av_money($_POST['monto']??0);$fecha=$_POST['fecha_pago']??'';$met=$_POST['metodo_pago']??'';
 if($m<=0||!av_valid_date($fecha)||$fecha>date('Y-m-d')||!in_array($met,['efectivo','transferencia','tarjeta','pago_movil'],true))throw new RuntimeException('Revise importe, fecha y método de pago.');
 $db->beginTransaction();$q=$db->prepare('SELECT costo_total FROM fumigaciones_realizadas WHERE id=? FOR UPDATE');$q->execute([$id]);$current=$q->fetchColumn();if($current===false)throw new RuntimeException('Fumigación no encontrada.');
 $q=$db->prepare('SELECT COALESCE(SUM(monto),0) FROM pagos_fumigacion WHERE fumigacion_id=?');$q->execute([$id]);$paid=(float)$q->fetchColumn();$balance=round((float)$current-$paid,2);
 if($balance<=0||$m>$balance+0.001)throw new RuntimeException('La fumigación está pagada o el importe supera el saldo.');
 $db->prepare('INSERT INTO pagos_fumigacion(fumigacion_id,monto,fecha_pago,metodo_pago,referencia,observaciones) VALUES(?,?,?,?,?,?)')->execute([$id,$m,$fecha,$met,trim($_POST['referencia']??''),trim($_POST['observaciones']??'')]);
 $db->prepare('UPDATE fumigaciones_realizadas SET estado_pago=?,metodo_pago=? WHERE id=?')->execute([$m+0.001>=$balance?'Pagado':'Parcial',$met,$id]);$db->commit();header('Location:ver_fumigacion.php?id='.$id);exit;
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('[fumigacion] '.$e->getMessage());$error=$e instanceof PDOException?'No se pudo registrar el pago.':$e->getMessage();}
?><!doctype html><html lang="es"><head>
<?php if(function_exists('av_head')) av_head(); ?><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registrar pago</title><style>body{font-family:Arial;background:#f5f7f6;color:#25352d}.c{max-width:620px;margin:40px auto;background:#fff;padding:28px;border-radius:15px;box-shadow:0 8px 25px #0001}.sum{background:#eef6f0;padding:14px;border-radius:9px;margin:15px 0}label{font-weight:700;display:block;margin:13px 0 5px}input,select,textarea{width:100%;box-sizing:border-box;padding:11px;border:1px solid #ccd7d0;border-radius:8px}textarea{min-height:80px}.a{display:flex;gap:10px;margin-top:20px}.b{border:0;padding:11px 16px;border-radius:8px;background:#0f6c33;color:white;text-decoration:none}.s{background:#e8efea;color:#25352d}.e{background:#fff0ef;color:#a11d14;padding:10px;border-radius:8px}</style>    <link rel="stylesheet" href="../css/app-optimized.css?v=20260812c">
</head><body><div class="c"><h1>Registrar pago de fumigación</h1><p><?=htmlspecialchars($f['cliente']??'Cliente')?></p><div class="sum">Total: <b>$<?=number_format($total,2)?></b> · Pagado: <b>$<?=number_format($pagado,2)?></b> · Saldo: <b>$<?=number_format($saldo,2)?></b></div><?php if($error):?><p class="e"><?=htmlspecialchars($error)?></p><?php endif;?><?php if($saldo<=0):?><p>Esta fumigación ya está pagada.</p><a class="b s" href="ver_fumigacion.php?id=<?=$id?>">Volver</a><?php else:?><form method="post"><?php echo av_csrf_field(); ?><input type="hidden" name="fumigacion_id" value="<?=$id?>"><label>Monto</label><input type="number" name="monto" step="0.01" min="0.01" max="<?=$saldo?>" required value="<?=number_format($saldo,2,'.','')?>"><label>Fecha</label><input type="date" name="fecha_pago" required value="<?=date('Y-m-d')?>"><label>Método</label><select name="metodo_pago" required><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option><option value="pago_movil">Pago móvil</option></select><label>Referencia</label><input name="referencia"><label>Observaciones</label><textarea name="observaciones"></textarea><div class="a"><button class="b">Registrar pago</button><a class="b s" href="ver_fumigacion.php?id=<?=$id?>">Cancelar</a></div></form><?php endif;?></div></body></html>
